<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,errorMessage,type Page} from '../../api/http'
import {useAuthStore} from '../../stores/auth'
import IncomingReferencePicker from '../quality/IncomingReferencePicker.vue'
import ReadReference from '../master/ReadReference.vue'
import {definitions,status,type Row} from './model'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),def=computed(()=>{const source=definitions[String(route.meta.resource)]!;return route.meta.receivingOnly?{...source,title:'成品生产入库（待检）',create:undefined,states:['SUBMITTED','CONFIRMED']}:source}),filters=ref({keyword:'',status:'',mainBatchId:''}),data=ref<Page<Row>>({items:[],total:0,page:0,size:20}),busy=ref(false),error=ref('')
const columns=computed(()=>{const resource=String(route.meta.resource),receiving=route.meta.receivingOnly;const source={title:resource==='sampling'||resource==='reports'?'成品请验单':'生产批',key:'source'};return [{title:receiving?'入库申请单号':resource==='inbound'?'入库申请单号':resource==='requests'?'请验单号':resource==='sampling'?'取样编号':resource==='reports'?'检验报告编号':'发货出库单号',dataIndex:def.value.number},source,...(receiving||resource==='requests'?[{title:'成品批次',key:'lot'}]:resource==='inbound'||resource==='shipments'?[{title:'产品',key:'product'}]:resource==='sampling'?[{title:'样品编号',key:'sample'}]:[]),...(resource==='requests'?[]:[{title:resource==='reports'?'综合结论':resource==='sampling'?'取样数量':resource==='shipments'?'发货数量':'数量',key:'quantity'}]),...(resource==='shipments'?[{title:'接收方',dataIndex:'receivingParty'}]:[]),...(resource==='sampling'?[]:[{title:receiving?'仓库接收状态':'状态',key:'status'}]),...(receiving?[{title:'实际质量状态',key:'quality'}]:[]),{title:receiving?'确认时间':resource==='sampling'?'取样时间':resource==='reports'?'生成时间':'创建时间',dataIndex:receiving?'confirmedAt':resource==='sampling'?'sampledAt':resource==='reports'?'generatedAt':'createdAt'},{title:'操作',key:'actions'}]})
let generation=0
async function load(page=0){const ticket=++generation,url=def.value.api;busy.value=true;error.value='';try{const params={page,size:20,...(route.meta.receivingOnly?{receivingOnly:true}:{}),keyword:filters.value.keyword||undefined,...(def.value.states.length?{status:filters.value.status||undefined}:{}),...(['inbound','requests','shipments'].includes(String(route.meta.resource))?{mainBatchId:filters.value.mainBatchId||undefined}:{})};await router.replace({query:Object.fromEntries(Object.entries(params).filter(([,v])=>v!==undefined).map(([k,v])=>[k,String(v)]))});if(ticket!==generation)return;const result=await api<Page<Row>>({url,params});if(ticket===generation)data.value=result}catch(e){if(ticket===generation)error.value=errorMessage(e)}finally{if(ticket===generation)busy.value=false}}watch(()=>[route.meta.resource,route.meta.receivingOnly].join(':'),()=>{data.value={items:[],total:0,page:0,size:20};filters.value={keyword:String(route.query.keyword??''),status:String(route.query.status??''),mainBatchId:String(route.query.mainBatchId??'')};void load(Number(route.query.page??0))},{immediate:true})
</script><template><main data-ui-template="T1" class="admin-page master-page t1-query-list"><header class="admin-page-header"><div><h1>{{def.title}}</h1><p>{{route.meta.receivingOnly?'展示待仓库确认及已确认的真实接收记录；质量状态以成品批次事实为准。':'成品受控业务记录 · 生产批、质量证据与库存追溯'}}</p></div><a-button v-if="def.create&&auth.can(def.permission+':create')" type="primary" @click="router.push(def.path+'/create')">＋ 新增{{def.title}}</a-button></header><a-card title="查询条件" class="query-card"><form class="query-form" @submit.prevent="load()"><label><span class="form-field-label">关键字</span><a-input v-model:value="filters.keyword" aria-label="关键字"/></label><label v-if="auth.can('production:batch:view')&&['inbound','requests','shipments'].includes(String(route.meta.resource))"><span class="form-field-label">生产批</span><IncomingReferencePicker v-model="filters.mainBatchId" field="mainBatchId" :context="{}" input-label="生产批查询"/></label><label v-if="def.states.length"><span class="form-field-label">状态</span><a-select v-model:value="filters.status" allow-clear aria-label="状态"><a-select-option v-for="s in def.states" :key="s" :value="s">{{status[s]}}</a-select-option></a-select></label><a-space><a-button @click="filters={keyword:'',status:'',mainBatchId:''};load()">重置</a-button><a-button type="primary" html-type="submit">查询</a-button></a-space></form></a-card><a-alert v-if="error" type="error" :message="error" show-icon/><a-card title="数据列表" class="result-card"><a-table :columns="columns" :data-source="data.items" row-key="id" :loading="busy" :pagination="false" :scroll="{x:900}"><template #bodyCell="{column,record}"><ReadReference v-if="column.key==='source'&&record.mainBatchId" field="mainBatchId" :value="record.mainBatchId" :name="record.batch?.batchNo" fallback="暂无可读生产批号"/><template v-else-if="column.key==='source'"><a-button v-if="record.inspectionRequestId&&auth.can('qms:finished-request:view')" type="link" @click="router.push('/finished/requests/'+record.inspectionRequestId)"><ReadReference field="finishedInspectionRequestId" :value="record.inspectionRequestId" fallback="暂无可读请验单编号"/></a-button><ReadReference v-else field="finishedInspectionRequestId" :value="record.inspectionRequestId" fallback="暂无可读请验单编号"/></template><ReadReference v-else-if="column.key==='product'" field="productId" :value="record.productId??record.batch?.productId" fallback="暂无可读产品名称"/><ReadReference v-else-if="column.key==='lot'" field="materialLotId" :value="record.materialLotId" :name="record.lot?.lotNo" fallback="暂无可读成品批号"/><ReadReference v-else-if="column.key==='sample'" field="productionSampleId" :value="record.sampleId" :name="record.sample?.sampleNo" fallback="暂无可读样品编号"/><span v-else-if="column.key==='quality'">{{record.lot?({QUARANTINE:'待检',RELEASED:'已放行',REJECTED:'不合格',LOCKED:'锁定',EXPIRED:'过期'} as Record<string,string>)[record.lot.qualityStatus]??record.lot.qualityStatus:'尚未形成库存批次'}}</span><span v-else-if="column.key==='quantity'">{{record.quantity??status[record.overallConclusion]??'—'}} <ReadReference v-if="record.unitId" field="unitId" :value="record.unitId" fallback="暂无可读单位名称"/></span><a-tag v-else-if="column.key==='status'">{{status[record.status]??'取样已记录'}}</a-tag><a-button v-else-if="column.key==='actions'" type="link" @click="router.push({path:def.path+'/'+record.id,query:route.query})">查看</a-button></template></a-table><div class="table-footer"><span>共 {{data.total}} 条</span><a-pagination :current="data.page+1" :page-size="data.size" :total="data.total" :show-size-changer="false" @change="(p:number)=>load(p-1)"/></div></a-card></main></template>
